export interface RenderForm {
  /** Modèle Word (.docx) ou OpenDocument (.odt), avec ses balises Docmosis ; ou bien templateName */
  template?: Blob | File;
  /** Chemin d'un modèle de la bibliothèque (version publiée) */
  templateName?: string;
  /** Données JSON du document (texte ou fichier) */
  data: string;
  /** Format du document produit */
  format?: RenderFormFormat;
  /** Nom du fichier rendu (Content-Disposition) */
  outputName?: string;
  /** Norme d'archivage ; défaut du réglage « PDF/A par défaut » */
  pdfa?: RenderFormPdfa;
  /** PDF balisé et conforme PDF/UA-1, lisible par les lecteurs d'écran ; sans titre (title) ni titre dans le modèle, le nom du document sert de titre. Avec PDF/A, choisir PDF/A-2b ou 3b (PDF/A-1b reste balisé mais sans la marque PDF/UA) */
  accessible?: boolean;
  /**
     * Texte du filigrane ; « none » pour aucun ; défaut du réglage « Filigrane »
     * @maxLength 100
     */
  watermark?: string;
  /** Couleur du filigrane, */
  watermarkColor?: string;
  /** Taille du texte en points (0 = automatique) */
  watermarkSize?: number;
  /** Angle en degrés */
  watermarkAngle?: number;
  /** Répéter le filigrane sur toute la page */
  watermarkTiled?: boolean;
  /** Contrôle des données attendues par le modèle ; défaut celui du modèle de la bibliothèque, sinon warn */
  dataCheck?: RenderFormDataCheck;
  /**
     * Mot de passe demandé à l'ouverture du PDF (pas avec PDF/A) ; jamais gardé dans l'historique
     * @maxLength 128
     */
  passwordProtect?: string;
  /**
     * Mot de passe du propriétaire, qui active les restrictions pdfRestrict…
     * @maxLength 128
     */
  pdfRestrictPassword?: string;
  /** 0 pas d'impression, 1 basse résolution, 2 pleine qualité (défaut) */
  pdfRestrictPrinting?: RenderFormPdfRestrictPrinting;
  /** 0 aucune modification … 4 tout sauf l'extraction de pages (défaut) */
  pdfRestrictEditing?: RenderFormPdfRestrictEditing;
  /** Interdire la copie du contenu */
  pdfRestrictCopy?: boolean;
  /** Interdire aussi l'accès des outils d'accessibilité (nom Docmosis) */
  pdfRestrictAllowAccessibilty?: boolean;
  /** Retirer les pages blanches ajoutées pour commencer sur une page paire ou impaire */
  pdfSkipEmptyPages?: boolean;
  /**
     * Titre du document (métadonnées du PDF)
     * @maxLength 500
     */
  title?: string;
  /**
     * Auteur (métadonnées du PDF)
     * @maxLength 500
     */
  author?: string;
  /**
     * Sujet (métadonnées du PDF)
     * @maxLength 500
     */
  subject?: string;
  /**
     * Mots-clés, séparés par des virgules (métadonnées du PDF)
     * @maxLength 500
     */
  keywords?: string;
  /** Mode développeur (nom Docmosis) ; les données absentes et les expressions illisibles sont écrites en surbrillance dans le document */
  devMode?: boolean;
  /** Cachet électronique de l'organisation (signature PAdES qui certifie le PDF) ; serveur configuré avec SEAL_CERT et SEAL_KEY ; incompatible avec un mot de passe */
  seal?: boolean;
}

