type SecondParameter<T extends (...args: never) => unknown> = Parameters<T>[1];



const withQueryKey = <T extends object, K>(query: T, queryKey: K): T & { queryKey: K } => {
  const result = { queryKey } as T & { queryKey: K };
  for (const key of Object.keys(query)) {
    // The explicit queryKey always wins, matching the previous
    // `{ ...query, queryKey }` spread where it was set last.
    if (key === 'queryKey') continue;
    Object.defineProperty(result, key, {
      enumerable: true,
      configurable: true,
      get: () => (query as Record<string, unknown>)[key],
    });
  }
  return result;
};

export const getRenderDocumentUrl = () => {




  return `/v1/render`
}

/**
 * Envoyez le modèle Word (.docx, avec ses balises Docmosis), ou le nom d'un modèle de la
 * bibliothèque (templateName), et les données JSON ; la réponse est le document (PDF par
 * défaut). Ni le document ni ses données ne sont gardés.
 *
 *     curl -H "Authorization: Bearer $DOCIBIS_API_KEY" \
 *       -F templateName=acme/contracts/broker/monthly/fiche_conseil.docx \
 *       -F data=@donnees.json -o document.pdf https://<instance>/v1/render
 * @summary Produit un document à partir d'un modèle Word et de données JSON
 */
export const renderDocument = async (renderForm: RenderForm, options?: Parameters<typeof apiFetch>[1]): Promise<Blob> => {
    const formData = new FormData();
if(renderForm.template !== undefined) {
 formData.append(`template`, renderForm.template);
 }
if(renderForm.templateName !== undefined) {
 formData.append(`templateName`, renderForm.templateName);
 }
formData.append(`data`, renderForm.data);
if(renderForm.format !== undefined) {
 formData.append(`format`, renderForm.format);
 }
if(renderForm.outputName !== undefined) {
 formData.append(`outputName`, renderForm.outputName);
 }
if(renderForm.pdfa !== undefined) {
 formData.append(`pdfa`, renderForm.pdfa);
 }
if(renderForm.accessible !== undefined) {
 formData.append(`accessible`, renderForm.accessible.toString())
 }
if(renderForm.watermark !== undefined) {
 formData.append(`watermark`, renderForm.watermark);
 }
if(renderForm.watermarkColor !== undefined) {
 formData.append(`watermarkColor`, renderForm.watermarkColor);
 }
if(renderForm.watermarkSize !== undefined) {
 formData.append(`watermarkSize`, renderForm.watermarkSize.toString())
 }
if(renderForm.watermarkAngle !== undefined) {
 formData.append(`watermarkAngle`, renderForm.watermarkAngle.toString())
 }
if(renderForm.watermarkTiled !== undefined) {
 formData.append(`watermarkTiled`, renderForm.watermarkTiled.toString())
 }
if(renderForm.dataCheck !== undefined) {
 formData.append(`dataCheck`, renderForm.dataCheck);
 }
if(renderForm.passwordProtect !== undefined) {
 formData.append(`passwordProtect`, renderForm.passwordProtect);
 }
if(renderForm.pdfRestrictPassword !== undefined) {
 formData.append(`pdfRestrictPassword`, renderForm.pdfRestrictPassword);
 }
if(renderForm.pdfRestrictPrinting !== undefined) {
 formData.append(`pdfRestrictPrinting`, renderForm.pdfRestrictPrinting.toString())
 }
if(renderForm.pdfRestrictEditing !== undefined) {
 formData.append(`pdfRestrictEditing`, renderForm.pdfRestrictEditing.toString())
 }
if(renderForm.pdfRestrictCopy !== undefined) {
 formData.append(`pdfRestrictCopy`, renderForm.pdfRestrictCopy.toString())
 }
if(renderForm.pdfRestrictAllowAccessibilty !== undefined) {
 formData.append(`pdfRestrictAllowAccessibilty`, renderForm.pdfRestrictAllowAccessibilty.toString())
 }
if(renderForm.pdfSkipEmptyPages !== undefined) {
 formData.append(`pdfSkipEmptyPages`, renderForm.pdfSkipEmptyPages.toString())
 }
if(renderForm.title !== undefined) {
 formData.append(`title`, renderForm.title);
 }
if(renderForm.author !== undefined) {
 formData.append(`author`, renderForm.author);
 }
if(renderForm.subject !== undefined) {
 formData.append(`subject`, renderForm.subject);
 }
if(renderForm.keywords !== undefined) {
 formData.append(`keywords`, renderForm.keywords);
 }
if(renderForm.devMode !== undefined) {
 formData.append(`devMode`, renderForm.devMode.toString())
 }
if(renderForm.seal !== undefined) {
 formData.append(`seal`, renderForm.seal.toString())
 }

  return apiFetch<Blob>(getRenderDocumentUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





