export const getRenderBatchUrl = () => {




  return `/v1/render/batch`
}

/**
 * Chaque document vient d'un modèle de la bibliothèque et de ses données, ou d'un PDF fixe de la
 * bibliothèque (conditions générales…). Les documents sont produits en parallèle puis, avec
 * merge (par défaut), réunis dans l'ordre en un seul PDF.
 * @summary Produit plusieurs documents en un appel, fusionnés en un seul PDF ou rendus dans un zip
 */
export const renderBatch = async (batchRequest: BatchRequest, options?: Parameters<typeof apiFetch>[1]): Promise<Blob> => {

    const getHeaders = (h?: NonNullable<RequestInit['headers']>): Record<string, string | readonly string[]> => {
    if (!h) return {};
    if (h instanceof Headers) return Object.fromEntries(h.entries());
    if (Symbol.iterator in h) {
      return Object.fromEntries(
        Array.from(h as Iterable<Iterable<string>>, (entry) => Array.from(entry) as [string, string]),
      );
    }
    const headers: Record<string, string | readonly string[]> = {};
    for (const [name, value] of Object.entries<string | readonly string[] | undefined>(h)) {
      if (value !== undefined) headers[name] = value;
    }
    return headers;
  };
return apiFetch<Blob>(getRenderBatchUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...getHeaders(options?.headers) },
    body: JSON.stringify(batchRequest)
  }
);}





