/**
 * @summary Produit le PDF d'un modèle avec des données JSON ; rien n'est enregistré
 */
export const tryRender = async (tryRenderForm: TryRenderForm, options?: Parameters<typeof apiFetch>[1]): Promise<TryResult> => {
    const formData = new FormData();
if(tryRenderForm.template !== undefined) {
 formData.append(`template`, tryRenderForm.template);
 }
if(tryRenderForm.templateName !== undefined) {
 formData.append(`templateName`, tryRenderForm.templateName);
 }
formData.append(`data`, tryRenderForm.data);
if(tryRenderForm.format !== undefined) {
 formData.append(`format`, tryRenderForm.format);
 }
if(tryRenderForm.pdfa !== undefined) {
 formData.append(`pdfa`, tryRenderForm.pdfa);
 }
if(tryRenderForm.accessible !== undefined) {
 formData.append(`accessible`, tryRenderForm.accessible.toString())
 }
if(tryRenderForm.watermark !== undefined) {
 formData.append(`watermark`, tryRenderForm.watermark);
 }
if(tryRenderForm.watermarkColor !== undefined) {
 formData.append(`watermarkColor`, tryRenderForm.watermarkColor);
 }
if(tryRenderForm.watermarkSize !== undefined) {
 formData.append(`watermarkSize`, tryRenderForm.watermarkSize.toString())
 }
if(tryRenderForm.watermarkAngle !== undefined) {
 formData.append(`watermarkAngle`, tryRenderForm.watermarkAngle.toString())
 }
if(tryRenderForm.watermarkTiled !== undefined) {
 formData.append(`watermarkTiled`, tryRenderForm.watermarkTiled.toString())
 }
if(tryRenderForm.passwordProtect !== undefined) {
 formData.append(`passwordProtect`, tryRenderForm.passwordProtect);
 }
if(tryRenderForm.pdfRestrictPassword !== undefined) {
 formData.append(`pdfRestrictPassword`, tryRenderForm.pdfRestrictPassword);
 }
if(tryRenderForm.pdfRestrictPrinting !== undefined) {
 formData.append(`pdfRestrictPrinting`, tryRenderForm.pdfRestrictPrinting.toString())
 }
if(tryRenderForm.pdfRestrictEditing !== undefined) {
 formData.append(`pdfRestrictEditing`, tryRenderForm.pdfRestrictEditing.toString())
 }
if(tryRenderForm.pdfRestrictCopy !== undefined) {
 formData.append(`pdfRestrictCopy`, tryRenderForm.pdfRestrictCopy.toString())
 }
if(tryRenderForm.pdfRestrictAllowAccessibilty !== undefined) {
 formData.append(`pdfRestrictAllowAccessibilty`, tryRenderForm.pdfRestrictAllowAccessibilty.toString())
 }
if(tryRenderForm.pdfSkipEmptyPages !== undefined) {
 formData.append(`pdfSkipEmptyPages`, tryRenderForm.pdfSkipEmptyPages.toString())
 }
if(tryRenderForm.title !== undefined) {
 formData.append(`title`, tryRenderForm.title);
 }
if(tryRenderForm.author !== undefined) {
 formData.append(`author`, tryRenderForm.author);
 }
if(tryRenderForm.subject !== undefined) {
 formData.append(`subject`, tryRenderForm.subject);
 }
if(tryRenderForm.keywords !== undefined) {
 formData.append(`keywords`, tryRenderForm.keywords);
 }
if(tryRenderForm.devMode !== undefined) {
 formData.append(`devMode`, tryRenderForm.devMode.toString())
 }

  return apiFetch<TryResult>(getTryRenderUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





